  // Broken tool pairing (orphan results at any position, displaced results,
  // duplicate ids, unanswered calls) makes providers hard-400 EVERY
  // subsequent request; repair the payload, never the transcript.
  // gh-1449: the session's reported-orphan latch rides the repair — an
  // orphan is noted once, then dropped silently; the new keys merge back
  // into the owner set so the next request (and the pairing-heal retry)
  // sees them.
  final repaired = repairToolPairing(
    requestContext.messages,
    reportedOrphanKeys: config.reportedOrphanKeys ?? const <String>{},
  );
  if (repaired.report.notedOrphanKeys.isNotEmpty) {
    config.reportedOrphanKeys?.addAll(repaired.report.notedOrphanKeys);
  }
  if (!identical(repaired.messages, requestContext.messages)) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: repaired.messages,
      tools: requestContext.tools,
    );
  }
  // gh-1680: armed cap repair coalesces the payload; AC7 keeps the transcript untouched.
  requestContext = _applyMessageCapCoalesce(requestContext, capCoalesceTarget);
  // gh-1556: an armed session deadline rides every request payload as a
  // trailing `time-left:` line — a standalone user message, so it can
  // never break a call/result run (same seat as the misuse note below).
  // Payload-only: the transcript is never touched, and a null provider
  // result (deadline unset/cleared) keeps the request byte-for-byte.
  final budgetLine = config.budgetLineProvider?.call();
  if (budgetLine != null) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: [...requestContext.messages, UserMessage.text(budgetLine)],
      tools: requestContext.tools,
    );
  }
  // Issue #862: an armed corrective note rides the NEXT request payload as
  // a trailing user message — visible to the model, never in the transcript.
  // Drained ONCE by the caller ([_streamAssistantResponse], before the
  // attempt loop) and re-attached on every rebuild, so an over-window
  // retry cannot silently drop an already-armed note (issue #862 review).
  if (misuseNote != null) {
    requestContext = Context(
      systemPrompt: requestContext.systemPrompt,
      messages: [...requestContext.messages, UserMessage.text(misuseNote)],
      tools: requestContext.tools,
    );
  }
  return (requestContext, repaired.report);
}

/// Builds the outbound-request capture emitted with [ModelRequestEvent]
/// (issue #385): the cheap summary (message count/sizes, tool names,
/// bounded previews), the per-message block structure (F3), the full
/// system-prompt blob (F1), the complete tool-manifest blob (F2), and —
/// when [config.wireDump] is on — the RAW serialized request payload (F5;
/// hosts redact and cap before persisting).
ModelRequestEvent _captureRequest(AgentLoopConfig config, Context context) {
  final messages = [
    for (final message in context.messages)
      TrajectoryRequestMessageSummary(
        role: message.role,
        // Unserializable arguments degrade to the placeholder instead of
        // throwing mid-loop (issue #385 E3: never a crash).
        chars: _safeJsonEncode(message.toJson()).length,
        preview: _requestPreview(message),
        blocks: _requestBlocksOf(message),
      ),
  ];
  final tools = context.tools ?? const <Tool>[];
  final prompt = context.systemPrompt;
  final promptBlob = prompt == null || prompt.isEmpty
      ? null
      : TrajectoryPromptBlob.of(prompt);
  final manifestBlob = tools.isEmpty
      ? null
      : TrajectoryToolManifestBlob.of(tools);
  return ModelRequestEvent(
    // gh-1073: the per-message detail is capped to the newest tail — an
    // unbounded summary of a 1000-message request is what grew the ledger
    // records to ~0.5 MB each.
    detail: capTrajectoryRequestDetail(
      TrajectoryRequestDetail(
        messageCount: messages.length,
        systemPromptChars: prompt?.length ?? 0,
        toolCount: tools.length,
        toolNames: [for (final tool in tools) tool.name],
        messages: messages,
        systemPromptHash: promptBlob?.hash,
        toolManifestHash: manifestBlob?.hash,
      ),
    ),
    promptBlob: promptBlob,
    manifestBlob: manifestBlob,
    rawWireDump: config.wireDump ? trajectoryWireDumpPayload(context) : null,
  );
}

/// Block structure of one outbound request message (F3): bounded full
/// texts and `[image WxH]` markers per content block, in request order.
List<TrajectoryRequestMessageBlock> _requestBlocksOf(Message message) {
  final List<ContentBlock> blocks = switch (message) {
    UserMessage(:final content) =>
