          : List<ContentBlock>.of(content as List<ContentBlock>),
    AssistantMessage(:final content) => content,
    ToolResultMessage(:final content) => content,
    _ => const <ContentBlock>[],
  };
  return trajectoryRequestBlocks(blocks);
}

