      TrajectoryToolManifestBlob(
        hash: json['hash'] as String? ?? '',
        tools: [
          for (final tool in (json['tools'] as List?) ?? const [])
            TrajectoryToolManifestEntry.fromJson(
              (tool as Map).cast<String, dynamic>(),
            ),
        ],
      );
}

