  _liveStep = step;
  _partial = TrajectoryPartialAssistant(
    messageId:
        message.responseId ?? 'evt\u0000partial\u0000${++_eventCounter}',
    turn: turn,
    step: step,
    blocks: _partialBlocks(message.content),
    startedAt: message.timestamp,
