/// the upcoming stream belongs to.
void _attachRequestDetail(
  (int, int) turnStep,
  TrajectoryRequestDetail detail,
) {
  final key = '${turnStep.$1}\u0000${turnStep.$2}';
  final facts = _assistantRequests[key];
  if (facts != null) {
