  _rows.add(
    TrajectoryContextRecord(
      index: _rows.length + 1,
      recordId: trajectoryRecordId(
        kind: 'context',
        recordId: recordId,
        index: _rows.length + 1,
      ),
      text: text,
      previewMarkdown: text,
      startedAt: time,
    ),
