String _normalize(String jsonl) => jsonl
    // Bare uuid-shaped tokens anywhere: session ids in the header, the
    // agent inbox address the system prompt embeds.
    .replaceAllMapped(
      RegExp(
        r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-'
        r'[0-9a-fA-F]{4}-[0-9a-fA-F]{12}',
      ),
      (_) => 'UUID',
    )
    .replaceAllMapped(RegExp(r'"timestamp":"[^"]*"'), (_) => '"timestamp":"T"')
    .replaceAllMapped(RegExp(r'"timestamp":\d+'), (_) => '"timestamp":0')
    // gh-1241: the usage segment-start marker's informational `at` stamp
    // (like `timestamp`, it is wall-clock per run; the record itself is
    // identical across the three legacy configs and stays compared).
    .replaceAllMapped(RegExp(r'"at":"[^"]*"'), (_) => '"at":"T"')
    // gh-1440: the skills section's `scanned at` disclosure stamp is the
    // last discovery scan's wall-clock (rendered into the system prompt),
    // so it differs per run exactly like `timestamp`; the rest of the
    // prompt is identical across the three legacy configs and stays
    // compared.
    .replaceAllMapped(
      RegExp(r'skills index scanned at [0-9T:.\-+]+Z'),
      (_) => 'skills index scanned at T',
    )
    // Content hashes computed over uuid-carrying text differ per run.
    .replaceAllMapped(
      RegExp(r'"([a-zA-Z]*[hH]ash)":"[0-9a-f]{8,}"'),
      (m) => '"${m.group(1)}":"H"',
    )
    // Short per-run record ids (the uuidv7 random tail).
    .replaceAllMapped(
      RegExp(r'"(id|parentId)":"[0-9a-f]{8,}"'),
      (m) => '"${m.group(1)}":"X"',
    )
    // gh-1617 CI flake: `systemPromptChars` counts the RAW prompt, whose
    // skills-scan stamp renders with run-dependent ISO precision (Dart's
    // toIso8601String emits a 6-digit fraction when the scan time carries
    // microseconds, 3-digit millis when it lands on a whole microsecond —
    // a 3-char length drift), so two legacy runs with a BYTE-IDENTICAL
    // prompt text can report different lengths. The informational count
    // stops being compared; the prompt TEXT itself stays byte-compared.
    .replaceAllMapped(
      RegExp(r'"systemPromptChars":\d+'),
      (_) => '"systemPromptChars":0',
    );
