        '"$stamp\\n\\n<prompt body>"}}\n'
        '{"type":"custom","id":"X","parentId":"X","timestamp":"T",'
        '"customType":"model_request_summary","data":{"messageCount":1,'
        '"systemPromptChars":$chars,"toolCount":29,"toolNames":["read"]}}\n';
