      if (total <= maxBytes && now.difference(DateTime.fromMillisecondsSinceEpoch(file.mtimeMs)) <= ttl) {
        break;
      }
      final expired = now.difference(
        DateTime.fromMillisecondsSinceEpoch(file.mtimeMs),
      ) > ttl;
      // Expired files go regardless of the budget; beyond that only the
      // oldest files leave until the dir fits.
      if (!expired && total <= maxBytes) break;
      await remove(file);
    }
    return deleted;
  }

  /// Sweeps when a write crossed the byte budget or a sweep hour has
  /// elapsed (the TTL must advance even in sessions that never reach the
  /// budget).
  Future<void> _maybeSweep(int payloadBytes) async {
    _bytesSinceSweep += payloadBytes;
    final last = _lastSweepAt;
    final hourElapsed =
        last == null || _clock().difference(last) >= const Duration(hours: 1);
    if (_bytesSinceSweep < maxBytes && !hourElapsed) return;
    _bytesSinceSweep = 0;
    _lastSweepAt = _clock();
    await enforceBudget();
  }

