      () async {
    final rig = await _rig(requestBlobs: false, wireDump: true);
    rig.io.sendLine('go');
    await _settle(rig);
    await _exit(rig);

    expect(await _sessionJsonl(rig), contains('"trajectory_wire_dump"'));
  });
}

