    final store = TrajectoryRequestBlobStore(
      env: rig.env,
      sessionId: () => _sessionId(rig),
    );
    final detail = await store.readDetail(spillPath);
    expect(detail, isNotNull);
    expect(
      detail!.messages.first.blocks,
