    }
    if (trajectoryRequestBlobTtlDays != 30) {
      lines.add('  requestBlobTtlDays: $trajectoryRequestBlobTtlDays');
    }
    if (lines.isEmpty) return '';
    return 'trajectory:\n${lines.join('\n')}\n';
  }
