        isA<ConfigException>().having(
          (e) => e.message,
          'message',
          contains('unknown "trajectory" key'),
        ),
      ),
    );
  });

  test('rejects a non-boolean wireDump', () {
    final file = File('${tmp.path}/.fah/config.yaml');
